import { render, screen } from "@testing-library/react";
import { ApplicationStatusBadge } from "@/components/candidates/ApplicationStatusBadge";
import { JobStatusBadge } from "@/components/jobs/JobStatusBadge";
import { TimekeepingStatusBadge } from "@/components/timekeeping/StatusBadge";
import { StatusBadge as SuperAdminStatusBadge, DetailedStatusBadge } from "@/components/super-admin/StatusBadge";
import { StatusBadge as OnboardingStatusBadge } from "@/components/onboarding/shared/StatusBadge";

describe("status badges", () => {
  it("renders the application badge variants", () => {
    render(<ApplicationStatusBadge status="final interview" />);
    expect(screen.getByText("Final Interview")).toBeInTheDocument();
  });

  it("renders job, timekeeping, onboarding, and super-admin badges", () => {
    render(
      <div>
        <JobStatusBadge status="open" />
        <TimekeepingStatusBadge status="present" />
        <OnboardingStatusBadge status="approved" />
        <SuperAdminStatusBadge status="Active" />
        <DetailedStatusBadge status="approved" />
      </div>,
    );

    expect(screen.getByText("open")).toBeInTheDocument();
    expect(screen.getByText("Present")).toBeInTheDocument();
    expect(screen.getByText("Approved")).toBeInTheDocument();
    expect(screen.getByText("Active")).toBeInTheDocument();
  });
});
